SELECT ID AS id,
       ORDER_STATUS AS orderStatus,
       PLAN_ML AS planMl,
       ACTUAL_ML AS actualMl
FROM ws_order
WHERE CARD_ID = #{cardId}
  AND USER_ID = #{actorUserId}
  AND ORDER_TYPE = 1
  AND CREATE_TIME >= #{dayStart}
  AND CREATE_TIME < #{dayEnd}

